  margin: 0 auto;
  padding-bottom: 56px;
}

.topbar {
  display: flex;
  min-height: 72px;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-bottom: 1px solid #c9cec4;
}

.brand {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 10px;
  color: #1c211e;
  font-size: 15px;
  font-weight: 700;
}

.brand-mark {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 7px;
  color: #fff;
  background: #1d513d;
  font-size: 15px;
}

.local-status {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  color: #4d554f;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.status-dot {
  width: 8px;
  height: 8px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: #25845d;
  box-shadow: 0 0 0 3px #d9e8de;
}

main {
  display: grid;
  gap: 52px;
  padding-top: 64px;
}

.section-label {
  margin: 0 0 10px;
  color: #687069;
  font-size: 12px;
