const EDITABLE_APPLICATION_FIELDS = new Set<keyof UpdateApplicationInput>([
  "company",
  "position",
  "jobType",
  "location",
  "workMode",
  "salaryText",
  "source",
  "jobUrl",
  "deadline",
  "contact",
