.application-row-actions { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; }

.application-list-view { display: grid; gap: 8px; margin-top: 18px; }
.application-list-row { display: grid; grid-template-columns: minmax(0, 2fr) minmax(100px, 1fr) minmax(90px, .7fr) auto; align-items: center; gap: 12px; border: 1px solid #ccd1c8; border-radius: 6px; padding: 12px; background: #fff; }
.application-list-row > div:first-child { display: grid; min-width: 0; gap: 3px; }
.application-list-row span, .application-list-row strong { overflow-wrap: anywhere; }
.application-list-row span { color: #59615a; font-size: 13px; }

.stage-manager { margin-top: 28px; border-top: 1px solid #c9cec4; padding-top: 18px; }
.stage-manager__list { display: grid; gap: 8px; margin-top: 12px; }
.stage-manager__item { display: grid; grid-template-columns: minmax(0, 1fr) 90px auto auto auto auto; align-items: end; gap: 8px; border-bottom: 1px solid #e0e4dd; padding-bottom: 8px; }
.stage-manager__item input[type="color"] { height: 36px; padding: 3px; }

.application-detail { margin-top: 24px; border-top: 1px solid #c9cec4; padding-top: 18px; }
.application-detail[hidden], .application-list-view[hidden], .application-detail[hidden], .application-confirm[hidden] { display: none; }
.application-detail__content { display: grid; gap: 12px; margin-top: 14px; }
.application-detail__facts { display: grid; grid-template-columns: minmax(80px, 120px) minmax(0, 1fr); gap: 8px 14px; margin: 0; }
.application-detail__facts dt { color: #687069; font-size: 12px; font-weight: 650; }
.application-detail__facts dd { min-width: 0; margin: 0; overflow-wrap: anywhere; }
.application-long-text { max-height: 220px; overflow: auto; white-space: pre-wrap; }
.application-detail__actions { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 9px; align-items: end; }
.application-detail__content ul, .application-detail__content ol { margin: 0; padding-left: 22px; }
.application-detail__content li { overflow-wrap: anywhere; }

.application-confirm { position: fixed; z-index: 5; top: 50%; left: 50%; width: min(90vw, 460px); transform: translate(-50%, -50%); border: 1px solid #b35c35; border-radius: 6px; padding: 18px; background: #fff; box-shadow: 0 12px 40px rgb(32 37 34 / 20%); }
.application-confirm p { overflow-wrap: anywhere; }
.application-confirm > div { display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-end; }
.application-confirm button:first-child { border-color: #b35c35; color: #fff; background: #b35c35; }

@media (max-width: 720px) {
  .application-form__grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .application-list-row { grid-template-columns: minmax(0, 1fr) auto; }
  .application-list-row > div:nth-child(2), .application-list-row > div:nth-child(3) { font-size: 12px; }
  .application-detail__actions { grid-template-columns: minmax(0, 1fr); }
  .stage-manager__item { grid-template-columns: minmax(0, 1fr) 76px; }
}

@media (max-width: 480px) {
  .application-form__grid { grid-template-columns: minmax(0, 1fr); }
  .application-board__heading { align-items: stretch; flex-direction: column; }
  .application-board__controls { justify-content: flex-start; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
  }
}

